<?php
/** Slice 9 proof — the agents page and agents_settings_save (home-admin.md "Proof": agents.php). */
require __DIR__ . '/lib.php';

$w = home_world();
$hb = $w['handbook'];
$owner = as_member(OWNER);
pdo()->exec('UPDATE kn_settings SET expert_member_id = ' . SEAMUS . ', archivist_member_id = ' . ARCHIVIST . ' WHERE id = 1');
$man = json_decode(file_get_contents(APP_ROOT . '/maludb-os.json'), true);
$decl = array_column($man['agents'], null, 'key');
$tools = static fn (array $a): int => array_sum(array_map('count', $a['tool_grants']));

echo "1. The page\n";
$since = last_activity_id();
$r = page($owner, '/admin/agents');
$h = $r['body'];
ok($r['code'] === 200 && str_contains($h, 'id="agent-card-expert"') && str_contains($h, 'id="agent-card-archivist"') && count(activity('screen.view', $since)) === 1, 'the two agents maludb-os.json declares, a card each');
preg_match('#id="agent-card-archivist-duty">(.*?)</div>#s', $h, $m);
ok(str_contains(strip_tags($m[1] ?? ''), 'The Monday base report') && str_contains(strip_tags($m[1] ?? ''), 'Mondays at 06:45'), 'the Archivist\'s duty "The Monday base report" — Mondays at 06:45');
preg_match('#id="agent-card-expert-duty">(.*?)</div>#s', $h, $m2);
ok(str_contains(strip_tags($m2[1] ?? ''), 'No duty'), 'the expert has none: it works when it is asked');
ok(str_contains($h, 'Knowledge Expert — job description') && str_contains($h, 'Knowledge Archivist — job description'), 'the job description\'s first line of each');
ok(str_contains($h, count($decl['expert']['skills']) . ' skills · ' . $tools($decl['expert']) . ' tools granted') && str_contains($h, count($decl['archivist']['skills']) . ' skills · ' . $tools($decl['archivist']) . ' tools granted'), 'the skill and tool counts of each (' . count($decl['expert']['skills']) . ' / ' . $tools($decl['expert']) . ' and ' . count($decl['archivist']['skills']) . ' / ' . $tools($decl['archivist']) . ')');
ok(str_contains($h, 'id="agent-member-' . SEAMUS . '"') && str_contains($h, 'id="agent-member-' . ARCHIVIST . '"') && str_contains($h, 'id="agent-member-' . AGENT90 . '"') && !str_contains($h, 'id="agent-member-' . WATCHER . '"') && !str_contains($h, 'id="agent-member-' . PRIYA . '"'), 'the mirror\'s agent members (not the unadmitted Watcher, no person)');
ok(str_contains($h, 'id="agent-member-' . SEAMUS . '-expert"') && str_contains($h, 'id="agent-member-' . ARCHIVIST . '-archivist"') && str_contains($h, 'is SMOKE Seamus'), 'who is the expert and who the Archivist, marked');
pdo()->exec("INSERT INTO activity_log (actor_member_id, source, action) VALUES (" . SEAMUS . ", 'agent', 'agent.test')");
pdo()->exec("INSERT INTO agent_dispatches (record_type, record_id, agent_member_id, kind, via, acting_member_id, base_id, status, detail, attempts, answered_at) VALUES ('base', $hb, " . SEAMUS . ", 'propose_areas', 'chat', " . CARA . ", $hb, 'failed', 'x', 5, now())");
pdo()->exec("INSERT INTO agent_dispatches (record_type, record_id, agent_member_id, kind, via, acting_member_id, base_id, status) VALUES ('base', $hb, " . SEAMUS . ", 'draft_guidelines', 'chat', " . CARA . ", $hb, 'sent')");
pdo()->exec("INSERT INTO activity_log (actor_member_id, source, action, base_id, after) VALUES (" . ARCHIVIST . ", 'agent', 'notification.send', $hb, '{\"kind\": \"monday_note\", \"recipients\": 2}')");
$h = page($owner, '/admin/agents')['body'];
ok(str_contains($h, 'id="agent-member-' . SEAMUS . '-dispatch-failed"') && str_contains($h, 'href="/admin/dispatches?status=failed"') && str_contains($h, 'id="agent-member-' . SEAMUS . '-dispatch-sent"') && preg_match('#id="agent-member-' . SEAMUS . '-dispatch-failed"[^>]*>\\d+ failed<#', $h) === 1, 'dispatches by status, each linking to slice 8\'s page');
preg_match('#id="agent-member-' . SEAMUS . '".*?</div></div>#s', $h, $m3);
preg_match('#id="agent-member-' . AGENT90 . '".*?</div></div>#s', $h, $m4);
ok(!str_contains($m3[0] ?? '', 'last active never') && str_contains($m4[0] ?? '', 'last active never') && str_contains($h, 'No dispatch yet.'), 'each agent\'s last activity (Seamus has some, the new one none)');
ok(str_contains($h, 'id="agent-card-archivist-note"') && str_contains($h, 'told 2 curators'), 'the last Monday note sent: when, and to how many');
ok(str_contains($h, 'id="admin-agents-hr-link"') && str_contains($h, 'https://os.example.invalid/agents') && str_contains($h, 'Hiring an agent'), 'a note says hiring, grants and duties are the kernel\'s, with a link to Agent HR');
[$c, $d] = screen($owner, '/admin/agents');
ok($c === 200 && count($d['declared']) === 2 && $d['declared'][1]['duty']['schedule'] === 'Mondays at 06:45' && $d['expert_member_id'] === SEAMUS && $d['archivist_member_id'] === ARCHIVIST && count($d['agents']) === 3 && $d['last_note']['recipients'] === 2, 'JSON: declared, the agent members, who is who, the last note');
foreach ([CARA => 'a Curator', PRIYA => 'a Member'] as $mem => $who) { ok(page(as_member($mem), '/admin/agents')['code'] === 403, "$who → 403 (agents.settings)"); }
ok(page(as_member(AVERY), '/admin/agents')['code'] === 200, 'a second admin may open it');

echo "2. Naming the expert and the Archivist\n";
$set = static fn (): array => q('SELECT expert_member_id, archivist_member_id FROM kn_settings WHERE id = 1')[0];
$since = last_activity_id();
[$c, $b] = act($owner, '/admin/agents.php', ['expert' => PRIYA]);
ok($c === 422 && fields($b)['expert'] === 'The expert is an agent member.' && (int) $set()['expert_member_id'] === SEAMUS, 'naming a human as the expert → the trigger\'s words, on the field; nothing changed');
[$c, $b] = act($owner, '/admin/agents.php', ['archivist' => BEA]);
ok($c === 422 && fields($b)['archivist'] === 'The Archivist is an agent member.', '…and the same for the Archivist');
[$c, $b] = act($owner, '/admin/agents.php', ['expert' => 99999]);
ok($c === 422 && isset(fields($b)['expert']), 'a member that is not there → 422 on the field');
[$c, $b] = act($owner, '/admin/agents.php', ['expert' => 'Seamus']);
ok($c === 422 && isset(fields($b)['expert']), 'a name instead of an id → 422 (the actions server resolves names; this takes the id)');
[$c, $b] = act(as_member(CARA), '/admin/agents.php', ['expert' => AGENT90]);
ok($c === 403 && (int) $set()['expert_member_id'] === SEAMUS, 'a Curator may not');
[$c, $b] = act($owner, '/admin/agents.php', ['expert' => AGENT90]);
ok($c === 200 && ($b['ok'] ?? false) === true && $b['record_id'] === 1 && $b['location'] === '/admin/agents' && $b['refresh'] === 'settingsChanged' && (int) $set()['expert_member_id'] === AGENT90 && (int) $set()['archivist_member_id'] === ARCHIVIST, 'naming agent 90 → 200 {ok, did, record_id, location, refresh}; the Archivist (left out) stays');
$ev = activity('agents_settings.save', $since);
$a = after_of($ev[0] ?? ['after' => '{}']);
$bf = json_decode((string) ($ev[0]['before'] ?? '{}'), true);
ok(count($ev) === 1 && $a['expert_member_id'] === AGENT90 && $a['archivist_member_id'] === ARCHIVIST && $bf['expert_member_id'] === SEAMUS, 'agents_settings.save logged: the two member ids (after), what changed (before)');
$q = evidence_only_question($w);
$h = page(as_member(PRIYA), '/ask?base=' . $hb . '&c=' . rawurlencode((string) question_row($q)['conversation_id']))['body'];
ok(str_contains($h, 'id="ask-expert-' . $q . '"'), 'with an expert named, slice 5\'s "Ask the expert" appears for an evidence-only question');
chat_state(['chat' => ['run_id' => 9001, 'status' => 'succeeded', 'finished' => true, 'reply' => 'Ninety answers.', 'actions' => []]]);
act(as_member(PRIYA), '/questions/expert.php', ['question' => $q]);
$chats = chat_log();
ok(end($chats)['agent'] === (string) AGENT90, '…and it calls the agent that was named (agent 90)');
[$c, $b] = act($owner, '/admin/agents.php', ['expert' => '']);
ok($c === 200 && $set()['expert_member_id'] === null, 'an empty expert clears it');
pdo()->exec("UPDATE agent_dispatches SET status = 'failed' WHERE record_id = $q AND record_type = 'question'");
$h = page(as_member(PRIYA), '/ask?base=' . $hb . '&c=' . rawurlencode((string) question_row($q)['conversation_id']))['body'];
ok(str_contains($h, 'id="expert-unnamed-' . $q . '"') && str_contains($h, 'No expert is named yet') && str_contains($h, 'Admin › Agents'), 'with none named the turn says so, pointing at Admin › Agents');
[$c, $b] = act($owner, '/admin/agents.php', ['expert_member_id' => SEAMUS, 'archivist' => '']);
ok($c === 200 && (int) $set()['expert_member_id'] === SEAMUS && $set()['archivist_member_id'] === null, 'an agent may send the column\'s own name (expert_member_id); the Archivist cleared');
[$c, $b] = act($owner, '/admin/agents.php', ['expert' => SEAMUS, 'archivist' => ARCHIVIST]);
ok($c === 200 && (int) $set()['archivist_member_id'] === ARCHIVIST, 'both named again');
[$c, $b] = act($owner, '/admin/agents.php', ['expert' => SEAMUS, 'archivist' => ARCHIVIST]);
ok($c === 200 && str_contains((string) $b['did'], 'Nothing changed'), 'saving the same again says nothing changed');
finish();
